        <h1 className="text-4xl font-bold text-blue-600 mb-4">
          Tailwind is working 🎉
        </h1>
        <p className="text-gray-600 text-center">
          CampusConnect frontend is ready
        </p>
      </div>
    </div>
  );
}

export default Home;
